 void Export(Character c){var dialog=new SaveFileDialog{Title="Exporter Reply AI",Filter="Sauvegarde Reply AI|*.replyai.json",FileName=c==null?"ReplyAI-espace.replyai.json":"ReplyAI-personnage.replyai.json",DefaultExt=".replyai.json"};if(dialog.ShowDialog(w)!=true)return;DataFiles.AtomicWrite(dialog.FileName,DataFiles.Export(data,c));Note("Export enregistré. La clé API n’est pas incluse.");}
